function nfCorpActivate(view,title,crumb){v7ActivateNav(view);setPage(title,crumb||title);nfOpenNavForView(view)}
function nfCorpHero(kicker,title,desc,actions=""){return `<section class="nf-corp-hero"><div><span>${kicker}</span><h2>${title}</h2><p>${desc}</p></div><div class="nf-corp-actions">${actions}</div></section>`}
function nfCorpTabs(tabs,current,fn){return `<nav class="nf-corp-tabs">${tabs.map(t=>`<button class="${current===t?'active':''}" onclick="${fn}('${String(t).replace(/'/g,"\\'")}')">${nfEsc(t)}</button>`).join('')}</nav>`}
function nfKpiDrill(k){const l=String(k).toLowerCase();const onProfile=document.querySelector('.nav-item.active')?.dataset.view==='employeeProfile';
 const prof=[['kra','Targets & KRA'],['sop','SOP & Controls'],['training','Training'],['attendance','Attendance'],['present','Attendance'],['late','Attendance'],['leave','Attendance'],['task','Tasks']];
 if(onProfile){const m=prof.find(([x])=>l.includes(x));if(m&&nfCorp.profileTab!==m[1])return nfSetProfileTab(m[1]);}
 if(l.includes('task'))return navTo('taskSla');
 if(/attrition|hiring|headcount|employee/.test(l))return navTo('hrms');
 if(/training|sop|compliance/.test(l))return navTo('complianceManagement');
 if(/attendance|leave/.test(l))return navTo('hrms');
 showToast(k+' — drill-down detail shown in the panels below');}
function nfCorpKpis(items){return `<div class="nf-corp-kpis">${items.map(([k,v,s,view])=>`<button onclick="${view?`navTo('${view}')`:`nfKpiDrill('${nfEsc(k).replace(/'/g,'')}')`}"><span>${nfEsc(k)}</span><b>${v}</b><small>${nfEsc(s||'')}</small></button>`).join('')}</div>`}
function nfCorpPanel(title,sub,body,action=""){return `<section class="nf-corp-panel"><div class="nf-corp-panel-head"><div><h3>${title}</h3><p>${sub||''}</p></div>${action}</div>${body}</section>`}
function nfCorpTable(headers,rows){return `<div class="nf-corp-table-wrap"><table class="nf-corp-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function nfCorpEmpty(text){return `<div class="nf-corp-empty">${text}</div>`}
function nfBars(items){return `<div class="nf-corp-bars">${items.map(([x,v])=>`<div><span>${nfEsc(x)}</span><b>${v}%</b><i><em style="width:${v}%"></em></i></div>`).join('')}</div>`}

