function toggleNavGroup(group,force){const g=document.querySelector(`.nf-nav-group[data-group="${group}"]`);if(!g)return;const open=force===undefined?!g.classList.contains("open"):!!force;document.querySelectorAll(".nf-nav-group").forEach(x=>x.classList.remove("open"));if(open)g.classList.add("open")}
function nfOpenNavForView(view){const group=Object.keys(NF_NAV_MAP).find(g=>NF_NAV_MAP[g].includes(view));if(group)toggleNavGroup(group,true)}
function nfUpdateNavGroups(){document.querySelectorAll(".nf-nav-group").forEach(g=>{const visible=[...g.querySelectorAll(".nav-item")].some(x=>!x.classList.contains("rbac-hidden"));g.classList.toggle("rbac-hidden",!visible)})}
const __nfApplyRole=applyRoleAccess; applyRoleAccess=function(){__nfApplyRole();nfUpdateNavGroups()};

function openAppLauncher(){
 const groups=[
  ["My Work",[["My Lobby","lobby","◉"],["My Tasks","taskSla","◷"],["Approvals","approvals","✓"],["Send Back","sendBack","↩"]]],
  ["Lending",[["CRM & Leads","crm","◎"],["LOS Application","newApplication","＋"],["Applications","applications","▤"],["Customer 360","customer360","◉"],["Credit & CAM","credit","✓"],["Underwriting","underwriting","◆"],["Sanction","sanction","✓"],["Operations","operations","◫"],["Disbursement","disbursement","₹"],["Deal / LMS","dealMovement","⇢"]]],
  ["People & Work",[["Employee 360","employeeProfile","♙"],["HRMS","hrms","👥"],["Projects & Tasks","projectTasks","◈"]]],
  ["Assets & Admin",[["IT & Non-IT Assets","assetInventory","▦"],["Admin Management","adminManagement","⌂"],["CCTV Monitoring","cctvMonitoring","◉"],["Travel Management","travelManagement","✈"]]],
  ["Governance",[["Audit Management","auditManagement","⌘"],["Compliance Management","complianceManagement","§"],["Consent & Control Log","auditCompliance","◇"],["Workflow & Access","workflowControl","⚙"]]],
  ["Insights & Platform",[["Reports & MIS","reports","⌁"],["Configuration Studio","configStudio","⚙"],["Integration Hub","integrationHub","⇆"],["Platform Architecture","platformArchitecture","⬡"]]]
 ];
 const html=groups.map(([g,items])=>{const visible=items.filter(x=>roleCanView(x[1]));if(!visible.length)return "";return `<section class="nf-launch-group"><h4>${g}</h4><div class="nf-launch-grid">${visible.map(x=>`<button onclick="closeModal();navTo('${x[1]}')"><i>${x[2]}</i><b>${x[0]}</b><span>Open workspace →</span></button>`).join("")}</div></section>`}).join("");
 showModal("All Workspaces",`<div class="nf-launch-search"><input id="nfLauncherSearch" placeholder="Search workspace…" oninput="nfFilterLauncher(this.value)"></div><div id="nfLauncherBody">${html}</div>`);
}
function nfFilterLauncher(q){q=String(q||"").toLowerCase();document.querySelectorAll("#nfLauncherBody button").forEach(b=>b.classList.toggle("hidden",!b.textContent.toLowerCase().includes(q)));document.querySelectorAll("#nfLauncherBody .nf-launch-group").forEach(g=>g.classList.toggle("hidden",![...g.querySelectorAll("button")].some(b=>!b.classList.contains("hidden"))))}

