function renderEmployeeProfile(){
 nfCorpActivate("employeeProfile","Employee 360 Profile","People / Employee 360");
 const p={name:currentUser.name,role:currentUser.role,dept:currentUser.dept,...nfCorp.profile};
 const tabs=["Overview","Targets & KRA","Tasks","Calendar","SOP & Controls","Training","Attendance","Documents & Assets"];
 let body="";
 if(nfCorp.profileTab==="Overview") body=`<div class="nf-corp-two">${nfCorpPanel("Work Summary","Role-linked workload and organization context",`<div class="nf-profile-summary"><div><span>Department</span><b>${nfEsc(p.dept)}</b></div><div><span>Reporting To</span><b>${nfEsc(roleMeta(currentUser.role).manager||"Board / CEO")}</b></div><div><span>Location</span><b>${nfEsc(p.location)}</b></div><div><span>Joining</span><b>${nfEsc(p.joining)}</b></div><div><span>Mobile</span><b>${nfEsc(p.mobile)}</b></div><div><span>Email</span><b>${nfEsc(p.email)}</b></div></div>`)}${nfCorpPanel("Current Assignments","Project and workflow tasks",`<div class="nf-corp-list">${nfCorp.projectTasks.filter(t=>t.owner===currentUser.name||currentUser.role==="CEO").slice(0,5).map(t=>`<button onclick="navTo('projectTasks')"><i>◈</i><span><b>${nfEsc(t.key)} · ${nfEsc(t.title)}</b><small>${nfEsc(t.status)} · Due ${nfEsc(t.due)}</small></span>${nfPill(t.priority)}</button>`).join("")||nfCorpEmpty("No linked project tasks")}</div>`)}</div>`;
 if(nfCorp.profileTab==="Targets & KRA") body=`${nfCorpKpis([["KRA Score",p.kra+"%","Weighted goals"],["SOP Compliance",p.sop+"%","Mandatory controls"],["Attendance",p.attendance+"%","Current month"],["Training",p.training+"%","Learning compliance"]])}<div class="nf-corp-two">${nfCorpPanel("KRA / KPI Scorecard","Role-specific outcome metrics",nfBars([["SLA Adherence",92],["Quality / Accuracy",89],["Productivity",86],["Stakeholder Rating",94],["Compliance",96]]))}${nfCorpPanel("Monthly Targets","Role objectives",`<div class="nf-corp-list">${[["Tasks / Cases Completed","84%"],["TAT Achievement","91%"],["Zero-defect Compliance","96%"],["Learning Completion","91%"]].map(x=>`<div class="nf-corp-static"><span>${x[0]}</span><b>${x[1]}</b></div>`).join("")}</div>`)}</div>`;
 if(nfCorp.profileTab==="Tasks") body=nfCorpPanel("My Tasks","Personal tasks plus enterprise work",`<div class="nf-corp-list">${nfCorp.employeeTasks.map(t=>`<div class="nf-corp-static"><span><b>${nfEsc(t.title)}</b><small>${nfEsc(t.id)} · Due ${nfEsc(t.due)}</small></span>${nfPill(t.status)}${t.status!=="Completed"?`<button class="nf-mini" onclick="nfCompleteEmployeeTask('${t.id}')">Complete</button>`:""}</div>`).join("")}</div>`,`<button class="nf-mini primary" onclick="nfAddEmployeeTask()">＋ Assign Task</button>`);
 if(nfCorp.profileTab==="Calendar") body=nfRenderEmployeeCalendar();
 if(nfCorp.profileTab==="SOP & Controls") body=nfCorpPanel("Role SOP & Mandatory Controls","Interactive checklist for operational readiness",`<div class="nf-sop-grid">${["Login & security check","Review assigned lobby","Validate mandatory evidence","Record action remarks","Follow maker-checker rule","Update task status","Escalate SLA breach","Complete compliance checks","Attach supporting document","Close with audit trail","Review pending approvals","Daily handoff / EOD"].map((s,i)=>`<button class="${i<9?"done":""}" onclick="this.classList.toggle('done')"><i>${i<9?"✓":i+1}</i><span>${s}</span></button>`).join("")}</div>`);
 if(nfCorp.profileTab==="Training") body=nfCorpPanel("Learning & Certification","Mandatory and role-based learning",`<div class="nf-corp-list">${nfCorp.training.map(t=>`<div class="nf-corp-static"><span><b>${nfEsc(t.name)}</b><small>${t.progress}% complete</small></span><div class="nf-inline-progress"><i style="width:${t.progress}%"></i></div>${nfPill(t.status)}</div>`).join("")}</div>`,`<button class="nf-mini" onclick="nfAssignTraining()">＋ Assign Learning</button>`);
 if(nfCorp.profileTab==="Attendance") body=`${nfCorpKpis([["Present",23,"This month"],["Late",1,"Regularized"],["Leave",1,"Approved"],["Attendance",p.attendance+"%","Monthly"]])}${nfCorpPanel("Attendance Calendar","Daily attendance and exceptions",`<div class="nf-attendance-grid">${Array.from({length:31},(_,i)=>`<div class="${[6,13,20,27].includes(i)?"off":i===17?"leave":i===8?"late":"present"}"><span>${i+1}</span><small>${[6,13,20,27].includes(i)?"WO":i===17?"EL":i===8?"Late":"P"}</small></div>`).join("")}</div>`)}`;
 if(nfCorp.profileTab==="Documents & Assets") body=`<div class="nf-corp-two">${nfCorpPanel("Employee Documents","Employment and compliance records",`<div class="nf-corp-list">${nfCorp.employeeDocs.map(d=>`<div class="nf-corp-static"><span>${nfEsc(d.name)}</span>${nfPill(d.status)}</div>`).join("")}</div>`,`<button class="nf-mini" onclick="nfAddEmployeeDoc()">＋ Add Document</button>`)}${nfCorpPanel("Assigned Assets","Assets currently issued to this employee",`<div class="nf-corp-list">${nfCorp.assets.filter(a=>a.assigned===currentUser.name).map(a=>`<button onclick="navTo('assetInventory')"><i>▦</i><span><b>${nfEsc(a.name)}</b><small>${nfEsc(a.tag)} · ${nfEsc(a.category)}</small></span>${nfPill(a.status)}</button>`).join("")||nfCorpEmpty("No assigned assets")}</div>`)}</div>`;
 $("#content").innerHTML=`${nfCorpHero("PEOPLE INTELLIGENCE","Employee 360° Profile","Performance, tasks, learning, compliance, attendance and assets in one role-aware view.",`<button onclick="nfEditEmployeeProfile()">✎ Edit Profile</button><button class="primary" onclick="nfAddEmployeeTask()">＋ Assign Task</button>`)}<section class="nf-profile-card"><div class="nf-profile-avatar">${nfInitial(p.name)}</div><div class="nf-profile-id"><h3>${nfEsc(p.name)}</h3><p>${nfEsc(p.role)} · ${nfEsc(p.dept)}</p><div><span>Employee ID: NF-${nfInitial(p.name)}-${String(currentUser.level||1).padStart(3,"0")}</span><span>${nfEsc(p.location)}</span><span>${nfEsc(p.email)}</span></div></div>${nfPill(p.status)}</section>${nfCorpKpis([["KRA Score",p.kra+"%","↑ 4% vs last month"],["SOP Compliance",p.sop+"%","Mandatory workflow"],["Training",p.training+"%","Certification completion"],["Attendance",p.attendance+"%","Current month"],["Open Tasks",nfCorp.employeeTasks.filter(t=>t.status!=="Completed").length,"Personal action queue"]])}${nfCorpTabs(tabs,nfCorp.profileTab,"nfSetProfileTab")}${body}`;
}
function nfSetProfileTab(t){nfCorp.profileTab=t;nfCorpSave();renderEmployeeProfile()}
function nfEditEmployeeProfile(){showModal("Edit Employee Profile",`<div class="field-grid"><label>Mobile<input id="nfProfMobile" value="${nfEsc(nfCorp.profile.mobile)}"></label><label>Email<input id="nfProfEmail" value="${nfEsc(nfCorp.profile.email)}"></label><label>Location<input id="nfProfLocation" value="${nfEsc(nfCorp.profile.location)}"></label><label>Status<select id="nfProfStatus"><option>Active</option><option>Inactive</option><option>On Leave</option></select></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfSaveEmployeeProfile()">Save</button>`)}
function nfSaveEmployeeProfile(){nfCorp.profile.mobile=$("#nfProfMobile").value;nfCorp.profile.email=$("#nfProfEmail").value;nfCorp.profile.location=$("#nfProfLocation").value;nfCorp.profile.status=$("#nfProfStatus").value;nfCorpSave();closeModal();showToast("Employee profile updated");renderEmployeeProfile()}
function nfAddEmployeeTask(){showModal("Assign Employee Task",`<label>Task<input id="nfEmpTaskTitle" placeholder="Task title"></label><div class="field-grid"><label>Priority<select id="nfEmpTaskPriority"><option>Normal</option><option>Medium</option><option>High</option></select></label><label>Due<input id="nfEmpTaskDue" type="date" value="${nfToday()}"></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfSaveEmployeeTask()">Assign</button>`)}
function nfSaveEmployeeTask(){const title=$("#nfEmpTaskTitle").value.trim();if(!title)return showToast("Enter task title");nfCorp.employeeTasks.unshift({id:"EMP-T-"+Date.now().toString().slice(-5),title,priority:$("#nfEmpTaskPriority").value,status:"Open",due:$("#nfEmpTaskDue").value||"Today"});nfCorpSave();closeModal();showToast("Task assigned");nfCorp.profileTab="Tasks";renderEmployeeProfile()}
function nfCompleteEmployeeTask(id){const t=nfCorp.employeeTasks.find(x=>x.id===id);if(t)t.status="Completed";nfCorpSave();showToast("Task completed");renderEmployeeProfile()}
function nfAssignTraining(){showModal("Assign Learning",`<label>Course<input id="nfTrainingName" placeholder="Course / certification"></label>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfSaveTraining()">Assign</button>`)}
function nfSaveTraining(){const name=$("#nfTrainingName").value.trim();if(!name)return;nfCorp.training.unshift({id:"TRN-"+Date.now().toString().slice(-4),name,progress:0,status:"Assigned"});nfCorpSave();closeModal();showToast("Training assigned");renderEmployeeProfile()}
function nfAddEmployeeDoc(){showModal("Add Employee Document",`<label>Document Type<input id="nfEmpDoc" placeholder="Document name"></label><label>File<input type="file" id="nfEmpDocFile"></label>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfSaveEmployeeDoc()">Add</button>`)}
function nfSaveEmployeeDoc(){const name=$("#nfEmpDoc").value.trim();if(!name)return;nfCorp.employeeDocs.unshift({name,status:"Verified"});nfCorpSave();closeModal();showToast("Document added");renderEmployeeProfile()}
function nfRenderEmployeeCalendar(){const dates=Array.from({length:14},(_,i)=>{const d=new Date();d.setDate(d.getDate()+i-3);return d});const tasks=[...nfCorp.projectTasks,...nfCorp.employeeTasks.map(t=>({...t,key:t.id,owner:currentUser.name}))];return nfCorpPanel("My Work Calendar","Project tasks and personal assignments",`<div class="nf-work-calendar">${dates.map((d,i)=>`<div class="nf-cal-day ${i===3?"today":""}"><header><b>${d.toLocaleDateString("en-IN",{day:"2-digit"})}</b><span>${d.toLocaleDateString("en-IN",{weekday:"short"})}</span></header>${tasks.filter((_,x)=>(x+i)%7===0).slice(0,2).map(t=>`<button onclick="navTo('projectTasks')"><small>${nfEsc(t.key||t.id)}</small><b>${nfEsc(t.title)}</b></button>`).join("")}</div>`).join("")}</div>`)}

// HRMS
const NF_HR_TABS=["Dashboard","People","Recruitment","Onboarding","Attendance & Shift","Leave","Payroll","Performance","Training","Documents & Compliance","Exit / Full & Final","Reports"];
function renderHRMSWorkspace(){
 nfCorpActivate("hrms","HRMS","People / HRMS"); const tab=nfCorp.hrTab,total=nfCorp.employees.length,active=nfCorp.employees.filter(e=>e.status==="Active").length; let b="";
 if(tab==="Dashboard") b=`${nfCorpKpis([["Headcount",total,active+" active"],["Present Today",Math.round(total*.88),"Across branches"],["Leave Approval",nfCorp.leaves.filter(x=>x.status==="Pending").length,"Awaiting manager"],["New Joiners",nfCorp.onboarding.length,"Current onboarding"],["Payroll","Ready",nfMoney(nfCorp.employees.reduce((s,e)=>s+e.salary,0))+" gross"],["Training Compliance","91%","Mandatory learning"]])}<div class="nf-corp-three">${nfCorpPanel("Workforce Snapshot","Department capacity",nfBars([["Sales",88],["Credit",94],["Operations",91],["Technology",84],["Support",90]]))}${nfCorpPanel("HR Action Queue","What needs HR attention",`<div class="nf-corp-list">${[["Pending Leave","2 requests"],["Onboarding","2 employees"],["Probation Review","1 employee"],["Document Expiry","3 records"],["Payroll Exception","1 employee"]].map(x=>`<button onclick="showToast('${x[0]} opened')"><i>›</i><span><b>${x[0]}</b><small>${x[1]}</small></span></button>`).join("")}</div>`)}${nfCorpPanel("Quick Actions","Common HR workflows",`<div class="nf-quick-grid"><button onclick="nfHRAddEmployee()">＋ Employee</button><button onclick="nfHRSetTab('Recruitment')">Recruitment</button><button onclick="nfHRAddLeave()">Leave</button><button onclick="nfHRSetTab('Payroll')">Payroll</button><button onclick="nfHRSetTab('Documents & Compliance')">Compliance</button><button onclick="nfHRSetTab('Reports')">Reports</button></div>`)}</div>`;
 if(tab==="People") b=nfCorpPanel("Employee Directory","Single source of truth for workforce records",nfCorpTable(["Employee","Department","Branch","Status","Join Date","Attendance","Leave",""],nfCorp.employees.map(e=>`<tr><td><b>${nfEsc(e.name)}</b><small>${nfEsc(e.id)} · ${nfEsc(e.role)}</small></td><td>${nfEsc(e.dept)}</td><td>${nfEsc(e.branch)}</td><td>${nfPill(e.status)}</td><td>${e.join}</td><td><b>${e.attendance}%</b></td><td>${e.leave} days</td><td><button class="nf-mini" onclick="nfOpenEmployeeFromHR('${e.id}')">Open 360</button></td></tr>`)),`<button class="nf-mini primary" onclick="nfHRAddEmployee()">＋ Add Employee</button>`);
 if(tab==="Recruitment") b=nfCorpPanel("Recruitment Pipeline","Requisition → Screening → Interview → Offer → Documents → Joined",`<div class="nf-stage-line">${["Requisition","Screening","Interview","Offer","Documents","Joined"].map((x,i)=>`<div class="${i<2?"done":i===2?"active":""}">${x}</div>`).join("")}</div>${nfCorpTable(["Candidate","Role","Branch","Source","Stage","Updated",""],nfCorp.candidates.map(c=>`<tr><td><b>${nfEsc(c.name)}</b><small>${c.id}</small></td><td>${nfEsc(c.role)}</td><td>${nfEsc(c.branch)}</td><td>${nfEsc(c.source)}</td><td>${nfPill(c.stage)}</td><td>${c.updated}</td><td><button class="nf-mini" onclick="nfHRMoveCandidate('${c.id}')">Move Stage</button></td></tr>`))}`,`<button class="nf-mini primary" onclick="nfHRAddCandidate()">＋ Add Candidate</button>`);
 if(tab==="Onboarding") b=nfCorpPanel("Onboarding Control","Offer acceptance to system, asset and branch readiness",`<div class="nf-corp-list">${nfCorp.onboarding.map(o=>`<div class="nf-corp-static"><span><b>${nfEsc(o.name)} · ${nfEsc(o.role)}</b><small>${nfEsc(o.stage)} · Owner ${nfEsc(o.owner)} · Due ${o.due}</small></span><div class="nf-inline-progress"><i style="width:${o.progress}%"></i></div><b>${o.progress}%</b></div>`).join("")}</div>`);
 if(tab==="Attendance & Shift") b=`${nfCorpKpis([["Present",5,"Today"],["Late",1,"Today"],["Absent",0,"Today"],["Regularization",2,"Open"]])}${nfCorpPanel("Attendance & Shift Desk","Punch, shift, exception and regularization workflow",nfCorpTable(["Employee","Branch","Shift","In","Out","Status",""],nfCorp.employees.map((e,i)=>`<tr><td><b>${e.name}</b><small>${e.role}</small></td><td>${e.branch}</td><td>${i%2?"10:00-19:00":"09:30-18:30"}</td><td>${i===4?"10:14":"09:3"+i}</td><td>18:${30+i}</td><td>${nfPill(i===4?"Late":"Present")}</td><td><button class="nf-mini" onclick="showToast('Regularization opened')">Regularize</button></td></tr>`)))}`;
 if(tab==="Leave") b=nfCorpPanel("Leave Calendar & Requests","Request → manager approval → HR balance update",`<div class="nf-corp-list">${nfCorp.leaves.map(l=>`<div class="nf-corp-static"><span><b>${l.id} · ${nfEsc(l.employee)}</b><small>${nfEsc(l.type)} · ${l.from} → ${l.to} · ${l.days} day(s)</small></span>${nfPill(l.status)}${l.status==="Pending"?`<button class="nf-mini good" onclick="nfHRLeave('${l.id}','Approved')">Approve</button><button class="nf-mini bad" onclick="nfHRLeave('${l.id}','Rejected')">Reject</button>`:""}</div>`).join("")}</div>`,`<button class="nf-mini primary" onclick="nfHRAddLeave()">＋ Apply Leave</button>`);
 if(tab==="Payroll") b=`${nfCorpKpis([["Gross Payroll",nfMoney(nfCorp.employees.reduce((s,e)=>s+e.salary,0)),"Current cycle"],["Employees",total,"Payable"],["Exceptions",1,"Needs review"],["Payslips","Draft","Not released"]])}${nfCorpPanel("Payroll Processing","Attendance → earnings → deductions → maker → checker → payslip",`<div class="nf-stage-line">${["Attendance Freeze","Variable Pay","Deductions","Maker Review","Checker Approval","Payslip Release"].map((x,i)=>`<div class="${i<3?"done":i===3?"active":""}">${x}</div>`).join("")}</div><div class="nf-corp-list">${nfCorp.employees.map(e=>`<div class="nf-corp-static"><span><b>${e.name}</b><small>${e.role}</small></span><b>${nfMoney(e.salary)}</b>${nfPill("Ready")}</div>`).join("")}</div>`,`<button class="nf-mini primary" onclick="showToast('Payroll maker cycle started')">Run Payroll</button>`)}`;
 if(tab==="Performance") b=nfCorpPanel("Performance Management","KRA/KPI, review cycles and outcomes",nfCorpTable(["Employee","Role","KRA","SOP","Attendance","Rating",""],nfCorp.employees.map((e,i)=>`<tr><td><b>${e.name}</b></td><td>${e.role}</td><td>${84+i*2}%</td><td>${88+i}%</td><td>${e.attendance}%</td><td>${(4.1+i*.1).toFixed(1)} / 5</td><td><button class="nf-mini" onclick="showToast('Review form opened')">Review</button></td></tr>`)));
 if(tab==="Training") b=nfCorpPanel("Learning & Certification","Mandatory, role-based and regulatory training",nfCorpTable(["Program","Audience","Completion","Due","Status",""],[["Fair Practices Code","All Lending Roles","92%","15 Oct","In Progress"],["Information Security","All Employees","96%","10 Oct","In Progress"],["Credit Underwriting Refresher","Credit","84%","20 Oct","In Progress"],["POSH Annual","All Employees","100%","Completed","Completed"]].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${nfPill(x[4])}</td><td><button class="nf-mini" onclick="showToast('Training roster opened')">Roster</button></td></tr>`)),`<button class="nf-mini primary" onclick="nfAssignTraining()">＋ Assign Training</button>`);
 if(tab==="Documents & Compliance") b=nfCorpPanel("Employee Documents & Compliance","KYC, employment, bank, background and policy controls",nfCorpTable(["Employee","Identity","PAN","Bank","BGV","Policy Attestation",""],nfCorp.employees.map((e,i)=>`<tr><td><b>${e.name}</b></td><td>${nfPill("Verified")}</td><td>${nfPill("Verified")}</td><td>${nfPill(i===4?"Pending":"Verified")}</td><td>${nfPill("Verified")}</td><td>${nfPill(i===2?"Due":"Completed")}</td><td><button class="nf-mini" onclick="showToast('Employee compliance opened')">Open</button></td></tr>`)));
 if(tab==="Exit / Full & Final") b=nfCorpPanel("Exit / Full & Final","Resignation → notice → asset return → access revoke → clearance → settlement",`<div class="nf-stage-line">${["Resignation","Notice","Asset Return","Access Revoke","Department Clearance","F&F","Relieving"].map((x,i)=>`<div class="${i<2?"done":i===2?"active":""}">${x}</div>`).join("")}</div><div class="nf-corp-list"><div class="nf-corp-static"><span><b>No active exit case</b><small>Start an exit workflow when required.</small></span><button class="nf-mini primary" onclick="showToast('Exit workflow initiated')">Initiate Exit</button></div></div>`);
 if(tab==="Reports") b=`${nfCorpKpis([["Attrition","4.2%","YTD"],["Hiring TAT","18 days","Average"],["Attendance","96.1%","Enterprise"],["Training","91%","Compliance"]])}${nfCorpPanel("HR Management Reports","Workforce, payroll, attendance and performance",`<div class="nf-quick-grid">${["Headcount","Attendance","Payroll","Performance","Training","Compliance"].map(x=>`<button onclick="showToast('${x} report exported')">${x}</button>`).join("")}</div>`)}`;
 $("#content").innerHTML=`${nfCorpHero("NAMDEV FINVEST · PEOPLE OPERATIONS","HRMS",tab==="Dashboard"?"Complete HR lifecycle for branches, corporate and field teams.":"HRMS / "+tab,`<button onclick="nfHRSetTab('People')">People Directory</button><button class="primary" onclick="nfHRAddEmployee()">＋ Add Employee</button>`)}${nfCorpTabs(NF_HR_TABS,tab,"nfHRSetTab")}${b}`;
}
function nfHRSetTab(t){nfCorp.hrTab=t;nfCorpSave();renderHRMSWorkspace()}
function nfHRAddEmployee(){showModal("Add Employee",`<div class="field-grid"><label>Employee Name<input id="nfHrName"></label><label>Role<input id="nfHrRole"></label><label>Department<select id="nfHrDept"><option>Sales</option><option>Credit</option><option>Operations</option><option>Technical</option><option>Legal</option><option>Information Technology</option><option>Human Resources</option><option>Compliance</option><option>Internal Audit</option><option>Administration</option></select></label><label>Branch<input id="nfHrBranch" value="Corporate Office"></label><label>Joining Date<input id="nfHrJoin" type="date" value="${nfToday()}"></label><label>Monthly Salary<input id="nfHrSalary" type="number" value="50000"></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfHRSaveEmployee()">Create Employee</button>`)}
function nfHRSaveEmployee(){const name=$("#nfHrName").value.trim();if(!name)return showToast("Enter employee name");nfCorp.employees.unshift({id:"NF-EMP-"+Date.now().toString().slice(-5),name,role:$("#nfHrRole").value||"Executive",dept:$("#nfHrDept").value,branch:$("#nfHrBranch").value,status:"Active",manager:"Department Head",join:$("#nfHrJoin").value,salary:Number($("#nfHrSalary").value||0),attendance:100,leave:18});nfCorpSave();closeModal();nfCorp.hrTab="People";showToast("Employee created");renderHRMSWorkspace()}
function nfHRAddCandidate(){showModal("Add Candidate",`<div class="field-grid"><label>Candidate<input id="nfCanName"></label><label>Role<input id="nfCanRole"></label><label>Branch<input id="nfCanBranch" value="Jaipur"></label><label>Source<select id="nfCanSource"><option>Referral</option><option>Job Portal</option><option>LinkedIn</option><option>Agency</option></select></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfHRSaveCandidate()">Add Candidate</button>`)}
function nfHRSaveCandidate(){const name=$("#nfCanName").value.trim();if(!name)return;nfCorp.candidates.unshift({id:"CAN-"+Date.now().toString().slice(-5),name,role:$("#nfCanRole").value,branch:$("#nfCanBranch").value,source:$("#nfCanSource").value,stage:"Screening",updated:nfToday()});nfCorpSave();closeModal();renderHRMSWorkspace()}
function nfHRMoveCandidate(id){const c=nfCorp.candidates.find(x=>x.id===id);if(!c)return;const s=["Screening","Interview","Offer","Documents","Joined"];c.stage=s[Math.min(s.length-1,s.indexOf(c.stage)+1)];c.updated=nfToday();if(c.stage==="Joined"&&!nfCorp.onboarding.some(o=>o.id===c.id))nfCorp.onboarding.push({id:c.id,name:c.name,role:c.role,progress:20,owner:"HR Manager",due:nfToday(),stage:"Joining Pack"});nfCorpSave();showToast("Candidate moved to "+c.stage);renderHRMSWorkspace()}
function nfHRAddLeave(){showModal("Apply Leave",`<div class="field-grid"><label>Employee<select id="nfLeaveEmp">${nfCorp.employees.map(e=>`<option>${nfEsc(e.name)}</option>`).join("")}</select></label><label>Type<select id="nfLeaveType"><option>Casual Leave</option><option>Earned Leave</option><option>Sick Leave</option></select></label><label>From<input id="nfLeaveFrom" type="date" value="${nfToday()}"></label><label>To<input id="nfLeaveTo" type="date" value="${nfToday()}"></label></div><label>Reason<textarea id="nfLeaveReason" rows="3"></textarea></label>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfHRSaveLeave()">Submit</button>`)}
function nfHRSaveLeave(){nfCorp.leaves.unshift({id:"LV-"+Date.now().toString().slice(-4),employee:$("#nfLeaveEmp").value,type:$("#nfLeaveType").value,from:$("#nfLeaveFrom").value,to:$("#nfLeaveTo").value,days:1,reason:$("#nfLeaveReason").value,status:"Pending"});nfCorpSave();closeModal();nfCorp.hrTab="Leave";showToast("Leave request submitted");renderHRMSWorkspace()}
function nfHRLeave(id,status){const l=nfCorp.leaves.find(x=>x.id===id);if(l)l.status=status;nfCorpSave();showToast("Leave "+status.toLowerCase());renderHRMSWorkspace()}
function nfOpenEmployeeFromHR(id){const e=nfCorp.employees.find(x=>x.id===id);if(!e)return;showModal("Employee 360 · "+e.name,`<div class="nf-profile-summary"><div><span>Employee ID</span><b>${e.id}</b></div><div><span>Role</span><b>${e.role}</b></div><div><span>Department</span><b>${e.dept}</b></div><div><span>Branch</span><b>${e.branch}</b></div><div><span>Attendance</span><b>${e.attendance}%</b></div><div><span>Leave Balance</span><b>${e.leave} days</b></div></div>`)}

// Project & Task Management
const NF_PM_TABS=["Overview","Projects","My Tasks","Timeline","Risks & Capacity"];
function renderProjectTasks(){
  nfCorpActivate("projectTasks","Projects & Tasks","PMO / Projects & Tasks");
  const tab=nfCorp.projectTab,tasks=nfCorp.projectTasks,projects=nfCorp.projects;
  let b="";
  if(tab==="Overview") b=`${nfCorpKpis([["Active Projects",projects.filter(p=>p.status!=="Completed").length,"Portfolio"],["Open Tasks",tasks.filter(t=>t.status!=="Completed").length,"Delivery queue"],["Critical",tasks.filter(t=>t.priority==="Critical"&&t.status!=="Completed").length,"Needs attention"],["Completed",tasks.filter(t=>t.status==="Completed").length,"Closed issues"],["On-Time","86%","Current portfolio"]])}<div class="nf-corp-two">${nfCorpPanel("Project Portfolio","Program health and progress",`<div class="nf-corp-list">${projects.map(p=>`<button onclick="nfProjectOpen('${p.id}')"><i>${nfInitial(p.key)}</i><span><b>${nfEsc(p.key)} · ${nfEsc(p.name)}</b><small>${nfEsc(p.owner)} · Due ${nfEsc(p.due)}</small></span><div class="nf-inline-progress"><i style="width:${p.progress}%"></i></div><b>${p.progress}%</b></button>`).join("")}</div>`)}${nfCorpPanel("Priority Tasks","Jira-style linked issues",`<div class="nf-corp-list">${tasks.slice(0,6).map(t=>`<div class="nf-corp-static"><span><b>${nfEsc(t.key)} · ${nfEsc(t.title)}</b><small>${nfEsc(t.owner)} · ${nfEsc(t.workstream)} · Due ${nfEsc(t.due)}</small></span>${nfPill(t.status)}<button class="nf-mini" onclick="nfPMAdvance('${t.id}')">Advance</button></div>`).join("")}</div>`)}</div>`;
  if(tab==="Projects") b=nfCorpPanel("Project Register","Parent project → workstream → task hierarchy",nfCorpTable(["Project","Owner / Department","Priority","Budget","Timeline","Progress","Status",""],projects.map(p=>`<tr><td><b>${nfEsc(p.key)} · ${nfEsc(p.name)}</b></td><td>${nfEsc(p.owner)}<small>${nfEsc(p.dept)}</small></td><td>${nfPill(p.priority)}</td><td>${nfMoney(p.budget)}</td><td>${p.start}<small>→ ${p.due}</small></td><td><div class="nf-table-progress"><i style="width:${p.progress}%"></i></div><b>${p.progress}%</b></td><td>${nfPill(p.status)}</td><td><button class="nf-mini" onclick="nfProjectOpen('${p.id}')">Open</button></td></tr>`)),`<button class="nf-mini primary" onclick="nfPMNewProject()">＋ New Project</button>`);
  if(tab==="My Tasks") b=nfCorpPanel("Task Board","New / Assigned → In Progress → Awaiting Approval → Verification → Completed",`<div class="nf-kanban">${["New / Assigned","In Progress","Awaiting Approval","Verification","Completed"].map(s=>`<section><header><b>${s}</b><span>${tasks.filter(t=>nfNormalizeTaskStatus(t.status)===s).length}</span></header>${tasks.filter(t=>nfNormalizeTaskStatus(t.status)===s).map(t=>`<article><span>${nfEsc(t.key)}</span><h4>${nfEsc(t.title)}</h4><p>${nfEsc(t.owner)} · ${nfEsc(t.workstream)}</p><div>${nfPill(t.priority)}<button onclick="nfPMAdvance('${t.id}')">Move →</button></div></article>`).join("")||'<small>No tasks</small>'}</section>`).join("")}</div>`,`<button class="nf-mini primary" onclick="nfPMNewTask()">＋ New Task</button>`);
  if(tab==="Timeline") b=nfCorpPanel("Portfolio Timeline","Projects and key milestones",`<div class="nf-timeline-chart"><div class="head"><span>Project</span>${["Oct W1","Oct W2","Oct W3","Oct W4","Nov W1","Nov W2"].map(x=>`<b>${x}</b>`).join("")}</div>${projects.map((p,i)=>`<div class="row"><span><b>${nfEsc(p.key)}</b><small>${nfEsc(p.name)}</small></span>${Array.from({length:6},(_,x)=>`<i class="${x>=i&&x<=Math.min(5,i+2)?'fill':''}"></i>`).join("")}</div>`).join("")}</div>`);
  if(tab==="Risks & Capacity") b=`<div class="nf-corp-two">${nfCorpPanel("Risks & Blockers","Items requiring project-owner action",`<div class="nf-corp-list">${[["Regulatory dependency pending","Critical"],["Vendor API UAT delay","High"],["Branch device procurement lead time","Medium"],["Policy sign-off completed","Completed"]].map(x=>`<div class="nf-corp-static"><span><b>${x[0]}</b><small>Portfolio risk</small></span>${nfPill(x[1])}</div>`).join("")}</div>`)}${nfCorpPanel("Team Capacity","Current workload allocation",nfBars([["Kavita Rao",82],["Neha Jain",68],["Arun Joshi",74],["Compliance Manager",61],["Project Manager",77]]))}</div>`;
  $("#content").innerHTML=`${nfCorpHero("ENTERPRISE PMO","Projects & Task Management","Plan projects, create linked Jira-style tasks, assign ownership, track delivery, risks, capacity and milestones.",`<button onclick="nfPMNewProject()">＋ New Project</button><button class="primary" onclick="nfPMNewTask()">＋ New Task</button>`)}${nfCorpTabs(NF_PM_TABS,tab,"nfPMSetTab")}${b}`;
}
function nfPMSetTab(t){nfCorp.projectTab=t;nfCorpSave();renderProjectTasks()}
function nfNormalizeTaskStatus(s){if(s==="QC / Verification"||s==="Ready for Release")return "Verification";if(s==="On Hold")return "New / Assigned";return s}
function nfPMAdvance(id){const t=nfCorp.projectTasks.find(x=>x.id===id);if(!t)return;const s=["New / Assigned","In Progress","Awaiting Approval","Verification","Completed"],cur=nfNormalizeTaskStatus(t.status);t.status=s[Math.min(s.length-1,Math.max(0,s.indexOf(cur))+1)];nfCorpSave();showToast(t.key+" moved to "+t.status);renderProjectTasks()}
function nfPMNewProject(){showModal("Create Project",`<div class="field-grid"><label>Project Name<input id="nfPName"></label><label>Owner<input id="nfPOwner" value="${nfEsc(currentUser.name)}"></label><label>Department<input id="nfPDept" value="${nfEsc(currentUser.dept)}"></label><label>Priority<select id="nfPPriority"><option>Normal</option><option>Medium</option><option>High</option><option>Critical</option></select></label><label>Budget<input id="nfPBudget" type="number"></label><label>Due Date<input id="nfPDue" type="date"></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfPMSaveProject()">Create</button>`)}
function nfPMSaveProject(){const name=$("#nfPName").value.trim();if(!name)return;const id="PRJ-"+Date.now().toString().slice(-5),key=name.toUpperCase().replace(/[^A-Z0-9]/g,"").slice(0,7)||"PROJECT";nfCorp.projects.push({id,key,name,owner:$("#nfPOwner").value,dept:$("#nfPDept").value,status:"Planning",priority:$("#nfPPriority").value,progress:0,budget:Number($("#nfPBudget").value||0),start:nfToday(),due:$("#nfPDue").value||nfToday()});nfCorpSave();closeModal();showToast("Project created");nfCorp.projectTab="Projects";renderProjectTasks()}
function nfPMNewTask(projectId=""){showModal("Create Project Task",`<div class="field-grid"><label>Task Summary<input id="nfTTitle"></label><label>Parent Project<select id="nfTProject">${nfCorp.projects.map(p=>`<option value="${p.id}" ${p.id===projectId?'selected':''}>${nfEsc(p.key)} · ${nfEsc(p.name)}</option>`).join("")}</select></label><label>Owner<input id="nfTOwner" value="${nfEsc(currentUser.name)}"></label><label>Workstream<input id="nfTWorkstream" value="Operations"></label><label>Priority<select id="nfTPriority"><option>Normal</option><option>Medium</option><option>High</option><option>Critical</option></select></label><label>Due Date<input id="nfTDue" type="date"></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfPMSaveTask()">Create Task</button>`)}
function nfPMSaveTask(){const title=$("#nfTTitle").value.trim(),project=$("#nfTProject").value;if(!title||!project)return showToast("Task and project are required");const p=nfCorp.projects.find(x=>x.id===project),id="TSK-P-"+Date.now().toString().slice(-5);nfCorp.projectTasks.unshift({id,project,key:(p?.key||"TASK")+"-"+(nfCorp.projectTasks.length+1),title,owner:$("#nfTOwner").value,workstream:$("#nfTWorkstream").value,priority:$("#nfTPriority").value,status:"New / Assigned",due:$("#nfTDue").value||nfToday()});nfCorpSave();closeModal();showToast("Task created");nfCorp.projectTab="My Tasks";renderProjectTasks()}
function nfProjectOpen(id){const p=nfCorp.projects.find(x=>x.id===id);if(!p)return;const tasks=nfCorp.projectTasks.filter(t=>t.project===id);showModal(nfEsc(p.key)+" · "+nfEsc(p.name),`<div class="nf-profile-summary"><div><span>Owner</span><b>${nfEsc(p.owner)}</b></div><div><span>Department</span><b>${nfEsc(p.dept)}</b></div><div><span>Priority</span><b>${nfEsc(p.priority)}</b></div><div><span>Progress</span><b>${p.progress}%</b></div><div><span>Budget</span><b>${nfMoney(p.budget)}</b></div><div><span>Due</span><b>${p.due}</b></div></div><div style="height:12px"></div>${nfCorpTable(["Task","Owner","Status","Due"],tasks.map(t=>`<tr><td><b>${nfEsc(t.key)}</b><small>${nfEsc(t.title)}</small></td><td>${nfEsc(t.owner)}</td><td>${nfPill(t.status)}</td><td>${t.due}</td></tr>`))}`,`<button class="ghost-btn" onclick="closeModal()">Close</button><button class="primary-btn" onclick="closeModal();nfPMNewTask('${id}')">＋ Add Task</button>`)}

// IT & Non-IT Asset Management
const NF_ASSET_TABS=["Overview","Asset Register","Procurement & Inward","Assignment","Transfers","Repairs & AMC","Physical Audit","Vendors & Masters","Software Licenses","Disposal & E-Waste"];
function renderAssetInventory(){
  nfCorpActivate("assetInventory","IT & Non-IT Asset Management","Assets / Enterprise Inventory");const tab=nfCorp.assetTab,a=nfCorp.assets;let b="";
  if(tab==="Overview") b=`${nfCorpKpis([["Total Assets",a.length,"IT + Non-IT"],["IT Assets",a.filter(x=>x.type==="IT").length,"Technology estate"],["Non-IT Assets",a.filter(x=>x.type==="Non-IT").length,"Facilities & office"],["Assigned",a.filter(x=>["Assigned","In Use"].includes(x.status)).length,"In custody"],["AMC / Warranty",a.filter(x=>String(x.status).includes("AMC")).length,"Needs action"],["Open Requests",nfCorp.assetRequests.length,"Procurement / replace"]])}<div class="nf-corp-two">${nfCorpPanel("Asset Health","Lifecycle and control status",nfBars([["Tagged & Verified",96],["Assigned / Custody",82],["Warranty Active",78],["AMC Coverage",89],["Physical Audit",91]]))}${nfCorpPanel("Open Asset Requests","Employee and branch demand",`<div class="nf-corp-list">${nfCorp.assetRequests.map(r=>`<div class="nf-corp-static"><span><b>${nfEsc(r.id)} · ${nfEsc(r.item)}</b><small>${nfEsc(r.requester)} · ${nfEsc(r.type)} · ${r.date}</small></span>${nfPill(r.status)}<button class="nf-mini" onclick="nfAssetAdvanceRequest('${r.id}')">Advance</button></div>`).join("")}</div>`,`<button class="nf-mini primary" onclick="nfAssetNewRequest()">＋ New Request</button>`)}</div>`;
  if(tab==="Asset Register") b=nfCorpPanel("Asset Register","Tag-level asset master with custody, warranty and location",nfCorpTable(["Asset","Type / Category","Tag / Serial","Location","Assigned To","Value","Status",""],a.map(x=>`<tr><td><b>${nfEsc(x.name)}</b><small>${nfEsc(x.id)}</small></td><td>${nfEsc(x.type)}<small>${nfEsc(x.category)}</small></td><td>${nfEsc(x.tag)}<small>${nfEsc(x.serial)}</small></td><td>${nfEsc(x.location)}</td><td>${nfEsc(x.assigned)}</td><td>${nfMoney(x.value)}</td><td>${nfPill(x.status)}</td><td><button class="nf-mini" onclick="nfAssetOpen('${x.id}')">Open</button></td></tr>`)),`<button class="nf-mini primary" onclick="nfAssetAdd()">＋ Add Asset</button>`);
  if(tab==="Procurement & Inward") b=nfCorpPanel("Procurement & Inward","Request → approval → PO → GRN → verification → asset tag → capitalization",`<div class="nf-stage-line">${["Request","Approval","Purchase Order","Goods Receipt","QC / Verification","Asset Tagging","Capitalize"].map((x,i)=>`<div class="${i<4?'done':i===4?'active':''}">${x}</div>`).join("")}</div><div class="nf-corp-list">${nfCorp.assetRequests.map(r=>`<div class="nf-corp-static"><span><b>${nfEsc(r.id)} · ${nfEsc(r.item)}</b><small>${nfEsc(r.requester)} · ${nfEsc(r.type)}</small></span>${nfPill(r.status)}<button class="nf-mini" onclick="nfAssetAdvanceRequest('${r.id}')">Next Stage</button></div>`).join("")}</div>`);
  if(tab==="Assignment") b=nfCorpPanel("Asset Assignment & Custody","Asset → employee / branch → acknowledgment → custody",nfCorpTable(["Asset","Current Custody","Location","Status",""],a.map(x=>`<tr><td><b>${nfEsc(x.tag)}</b><small>${nfEsc(x.name)}</small></td><td>${nfEsc(x.assigned)}</td><td>${nfEsc(x.location)}</td><td>${nfPill(x.status)}</td><td><button class="nf-mini" onclick="nfAssetAssign('${x.id}')">Assign / Return</button></td></tr>`)));
  if(tab==="Transfers") b=nfCorpPanel("Inter-Branch / Department Transfers","Request → approval → dispatch → in transit → receive → physical verification",`<div class="nf-stage-line">${["Transfer Request","Approval","Dispatch","In Transit","Receive","Verify"].map((x,i)=>`<div class="${i<3?'done':i===3?'active':''}">${x}</div>`).join("")}</div>${nfCorpTable(["Asset","From","To","Status",""],a.slice(0,3).map((x,i)=>`<tr><td><b>${nfEsc(x.tag)}</b><small>${nfEsc(x.name)}</small></td><td>${nfEsc(x.location)}</td><td>${["Udaipur","Jaipur - Sanganer","Corporate Office"][i]}</td><td>${nfPill(i===0?'In Transit':'Planned')}</td><td><button class="nf-mini" onclick="nfAssetTransfer('${x.id}')">Transfer</button></td></tr>`))}`);
  if(tab==="Repairs & AMC") b=nfCorpPanel("Repairs, Warranty & AMC","Incident → service ticket → vendor → repair → verification → return to service",nfCorpTable(["Asset","Warranty / AMC","Vendor","Status",""],a.map(x=>`<tr><td><b>${nfEsc(x.tag)}</b><small>${nfEsc(x.name)}</small></td><td>${nfEsc(x.warranty)}</td><td>${nfEsc(x.vendor)}</td><td>${nfPill(x.status)}</td><td><button class="nf-mini" onclick="nfAssetRepair('${x.id}')">Service Ticket</button></td></tr>`)));
  if(tab==="Physical Audit") b=`${nfCorpKpis([["Audit Coverage","91%","Current cycle"],["Scanned",a.length,"Prototype sample"],["Matched",Math.max(0,a.length-1),"Physical = system"],["Variance",1,"Needs approval"]])}${nfCorpPanel("Physical Verification","Plan → scan tag → compare → variance → approval → adjustment",`<div class="nf-corp-list">${a.map((x,i)=>`<div class="nf-corp-static"><span><b>${nfEsc(x.tag)} · ${nfEsc(x.name)}</b><small>${nfEsc(x.location)}</small></span>${nfPill(i===2?'Variance':'Matched')}<button class="nf-mini" onclick="showToast('Asset verification recorded')">Verify</button></div>`).join("")}</div>`,`<button class="nf-mini primary" onclick="showToast('Audit cycle created')">＋ New Audit Cycle</button>`)}`;
  if(tab==="Vendors & Masters") b=nfCorpPanel("Vendors & Asset Masters","Categories, locations, vendors, depreciation and control setup",nfCorpTable(["Vendor","Service / Category","Rating","Open Work","Status"],[["TechNova Systems","Laptops & Endpoints","4.7 ★","2","Active"],["SecureNet","Network & Security","4.8 ★","1","Active"],["CoolAir Services","HVAC / AMC","4.3 ★","3","Active"],["OfficeCraft","Furniture","4.5 ★","0","Active"]].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${nfPill(x[4])}</td></tr>`)),`<button class="nf-mini primary" onclick="showToast('Vendor form opened')">＋ Add Vendor</button>`);
  if(tab==="Software Licenses") b=nfCorpPanel("Software Licenses","License inventory, assignment, renewal and compliance",nfCorpTable(["Product","Licenses","Used","Renewal","Owner","Status"],[["Microsoft 365",250,224,"15 Jan 2027","IT","Active"],["Endpoint Security",240,238,"30 Nov 2026","IT Security","Renewal Due"],["Adobe Acrobat",45,39,"18 Feb 2027","IT","Active"],["Power BI Pro",60,54,"01 Dec 2026","Analytics","Active"]].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td>${x[3]}</td><td>${x[4]}</td><td>${nfPill(x[5])}</td></tr>`)));
  if(tab==="Disposal & E-Waste") b=nfCorpPanel("Disposal & E-Waste","Identify → approval → data wipe → disposal vendor → certificate → asset retirement",`<div class="nf-stage-line">${["Identify","Approval","Data Wipe","Handover","E-Waste Certificate","Retire Asset"].map((x,i)=>`<div class="${i<2?'done':i===2?'active':''}">${x}</div>`).join("")}</div><div class="notice info">IT assets require certified data sanitization before disposal. Non-IT assets follow approved write-off / sale / scrap controls.</div>`);
  $("#content").innerHTML=`${nfCorpHero("ENTERPRISE ASSET CONTROL","IT & Non-IT Asset Management","Procurement, inward, tagging, assignment, branch transfer, repair, AMC, physical audit, licenses and disposal.",`<button onclick="nfAssetNewRequest()">＋ Asset Request</button><button class="primary" onclick="nfAssetAdd()">＋ Add Asset</button>`)}${nfCorpTabs(NF_ASSET_TABS,tab,"nfAssetSetTab")}${b}`;
}
function nfAssetSetTab(t){nfCorp.assetTab=t;nfCorpSave();renderAssetInventory()}
function nfAssetAdd(){showModal("Add Asset",`<div class="field-grid"><label>Asset Name<input id="nfAssetName"></label><label>Type<select id="nfAssetType"><option>IT</option><option>Non-IT</option></select></label><label>Category<input id="nfAssetCat" placeholder="Laptop, Printer, Furniture..."></label><label>Asset Tag<input id="nfAssetTag" value="NF-${Date.now().toString().slice(-5)}"></label><label>Serial No.<input id="nfAssetSerial"></label><label>Location<input id="nfAssetLocation" value="Corporate Office"></label><label>Value<input id="nfAssetValue" type="number"></label><label>Vendor<input id="nfAssetVendor"></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfAssetSave()">Create Asset</button>`)}
function nfAssetSave(){const name=$("#nfAssetName").value.trim();if(!name)return;nfCorp.assets.unshift({id:"AST-"+Date.now().toString().slice(-6),type:$("#nfAssetType").value,category:$("#nfAssetCat").value,name,tag:$("#nfAssetTag").value,serial:$("#nfAssetSerial").value||"—",location:$("#nfAssetLocation").value,assigned:"Unassigned",status:"Available",purchase:nfToday(),warranty:"—",value:Number($("#nfAssetValue").value||0),vendor:$("#nfAssetVendor").value||"—"});nfCorpSave();closeModal();showToast("Asset created");nfCorp.assetTab="Asset Register";renderAssetInventory()}
function nfAssetNewRequest(){showModal("New Asset Request",`<div class="field-grid"><label>Requester<input id="nfARReq" value="${nfEsc(currentUser.name)}"></label><label>Type<select id="nfARType"><option>IT</option><option>Non-IT</option></select></label><label>Item<input id="nfARItem"></label><label>Priority<select id="nfARPriority"><option>Normal</option><option>Medium</option><option>High</option></select></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfAssetSaveRequest()">Submit</button>`)}
function nfAssetSaveRequest(){nfCorp.assetRequests.unshift({id:"AR-"+Date.now().toString().slice(-4),requester:$("#nfARReq").value,item:$("#nfARItem").value,type:$("#nfARType").value,priority:$("#nfARPriority").value,status:"Pending Approval",date:nfToday()});nfCorpSave();closeModal();showToast("Asset request submitted");renderAssetInventory()}
function nfAssetAdvanceRequest(id){const r=nfCorp.assetRequests.find(x=>x.id===id);if(!r)return;const s=["Pending Approval","Approved","Procurement","Goods Received","Tagged","Closed"],i=s.indexOf(r.status);r.status=s[Math.min(s.length-1,i<0?1:i+1)];nfCorpSave();showToast(r.id+" moved to "+r.status);renderAssetInventory()}
function nfAssetOpen(id){const a=nfCorp.assets.find(x=>x.id===id);if(!a)return;showModal(nfEsc(a.tag)+" · "+nfEsc(a.name),`<div class="nf-profile-summary"><div><span>Type</span><b>${nfEsc(a.type)}</b></div><div><span>Category</span><b>${nfEsc(a.category)}</b></div><div><span>Serial</span><b>${nfEsc(a.serial)}</b></div><div><span>Location</span><b>${nfEsc(a.location)}</b></div><div><span>Custody</span><b>${nfEsc(a.assigned)}</b></div><div><span>Value</span><b>${nfMoney(a.value)}</b></div><div><span>Status</span><b>${nfEsc(a.status)}</b></div><div><span>Warranty</span><b>${nfEsc(a.warranty)}</b></div></div>`,`<button class="ghost-btn" onclick="closeModal()">Close</button><button class="primary-btn" onclick="closeModal();nfAssetAssign('${id}')">Assign / Return</button>`)}
function nfAssetAssign(id){const a=nfCorp.assets.find(x=>x.id===id);if(!a)return;showModal("Assign / Return Asset",`<label>Assign To<input id="nfAssignTo" value="${a.assigned==='Unassigned'?'':nfEsc(a.assigned)}"></label><label>Location<input id="nfAssignLoc" value="${nfEsc(a.location)}"></label>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfAssetSaveAssign('${id}')">Update Custody</button>`)}
function nfAssetSaveAssign(id){const a=nfCorp.assets.find(x=>x.id===id);a.assigned=$("#nfAssignTo").value||"Unassigned";a.location=$("#nfAssignLoc").value;a.status=a.assigned==="Unassigned"?"Available":"Assigned";nfCorpSave();closeModal();showToast("Asset custody updated");renderAssetInventory()}
function nfAssetTransfer(id){const a=nfCorp.assets.find(x=>x.id===id);if(!a)return;showModal("Transfer Asset",`<label>Destination<input id="nfTransferLoc" placeholder="Branch / department"></label>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfAssetSaveTransfer('${id}')">Dispatch</button>`)}
function nfAssetSaveTransfer(id){const a=nfCorp.assets.find(x=>x.id===id);a.location=$("#nfTransferLoc").value||a.location;a.status="In Transit";nfCorpSave();closeModal();showToast("Asset transfer initiated");renderAssetInventory()}
function nfAssetRepair(id){const a=nfCorp.assets.find(x=>x.id===id);if(!a)return;a.status="Repair / Service";nfCorpSave();showToast("Service ticket created for "+a.tag);renderAssetInventory()}

// Audit Management
const NF_AUDIT_TABS=["Dashboard","Audit Plan","Fieldwork","Observations","CAPA","Closure","Reports"];
function renderAuditManagement(){
 nfCorpActivate("auditManagement","Audit Management","Governance / Internal Audit");const tab=nfCorp.auditTab;let b="";
 if(tab==="Dashboard") b=`${nfCorpKpis([["Audits",nfCorp.audits.length,"Current plan"],["Fieldwork",nfCorp.audits.filter(a=>a.status==="Fieldwork").length,"In progress"],["Open Observations",nfCorp.observations.filter(o=>o.status!=="Closed").length,"Needs action"],["High Risk",nfCorp.observations.filter(o=>o.rating==="High").length,"Priority"],["CAPA Due",nfCorp.observations.filter(o=>o.status==="CAPA Submitted").length,"Validation queue"]])}<div class="nf-corp-two">${nfCorpPanel("Audit Universe & Plan","Risk-based audit portfolio",`<div class="nf-corp-list">${nfCorp.audits.map(a=>`<button onclick="nfAuditOpen('${a.id}')"><i>⌘</i><span><b>${nfEsc(a.id)} · ${nfEsc(a.title)}</b><small>${nfEsc(a.scope)} · ${nfEsc(a.owner)}</small></span><div class="nf-inline-progress"><i style="width:${a.progress}%"></i></div>${nfPill(a.status)}</button>`).join("")}</div>`)}${nfCorpPanel("Critical Observations","Management attention required",`<div class="nf-corp-list">${nfCorp.observations.map(o=>`<div class="nf-corp-static"><span><b>${nfEsc(o.id)} · ${nfEsc(o.title)}</b><small>${nfEsc(o.owner)} · Due ${nfEsc(o.due)}</small></span>${nfPill(o.rating)}${nfPill(o.status)}</div>`).join("")}</div>`)}</div>`;
 if(tab==="Audit Plan") b=nfCorpPanel("Annual / Quarterly Audit Plan","Plan → approve → assign → schedule",nfCorpTable(["Audit","Type","Scope","Owner","Risk","Start","Due","Status",""],nfCorp.audits.map(a=>`<tr><td><b>${nfEsc(a.id)}</b><small>${nfEsc(a.title)}</small></td><td>${nfEsc(a.type)}</td><td>${nfEsc(a.scope)}</td><td>${nfEsc(a.owner)}</td><td>${nfPill(a.risk)}</td><td>${a.start}</td><td>${a.due}</td><td>${nfPill(a.status)}</td><td><button class="nf-mini" onclick="nfAuditOpen('${a.id}')">Open</button></td></tr>`)),`<button class="nf-mini primary" onclick="nfAuditNew()">＋ New Audit</button>`);
 if(tab==="Fieldwork") b=nfCorpPanel("Fieldwork Workspace","Checklist → sample → evidence → test → observation",`<div class="nf-stage-line">${["Planning","Kick-off","Fieldwork","Evidence Review","Draft Findings","Exit Meeting"].map((x,i)=>`<div class="${i<2?'done':i===2?'active':''}">${x}</div>`).join("")}</div><div class="nf-corp-list">${nfCorp.audits.filter(a=>a.status==="Fieldwork").map(a=>`<div class="nf-corp-static"><span><b>${nfEsc(a.id)} · ${nfEsc(a.title)}</b><small>${nfEsc(a.auditee)} · ${nfEsc(a.scope)}</small></span><div class="nf-inline-progress"><i style="width:${a.progress}%"></i></div><button class="nf-mini" onclick="nfAuditAddObservation('${a.id}')">＋ Observation</button></div>`).join("")||nfCorpEmpty("No audit in fieldwork")}</div>`);
 if(tab==="Observations") b=nfCorpPanel("Audit Observations","Finding → rating → management response → CAPA → validation",nfCorpTable(["Observation","Audit","Rating","Owner","Due","Status","Response",""],nfCorp.observations.map(o=>`<tr><td><b>${nfEsc(o.id)}</b><small>${nfEsc(o.title)}</small></td><td>${nfEsc(o.audit)}</td><td>${nfPill(o.rating)}</td><td>${nfEsc(o.owner)}</td><td>${o.due}</td><td>${nfPill(o.status)}</td><td>${nfEsc(o.response)}</td><td><button class="nf-mini" onclick="nfAuditAdvanceObs('${o.id}')">Advance</button></td></tr>`)));
 if(tab==="CAPA") b=nfCorpPanel("Corrective & Preventive Action","Owner action plan → evidence → auditor validation",`<div class="nf-corp-list">${nfCorp.observations.filter(o=>o.status!=="Closed").map(o=>`<div class="nf-corp-static"><span><b>${nfEsc(o.id)} · ${nfEsc(o.title)}</b><small>${nfEsc(o.response||'Management response pending')} · Due ${o.due}</small></span>${nfPill(o.status)}<button class="nf-mini" onclick="nfAuditAdvanceObs('${o.id}')">Update CAPA</button></div>`).join("")}</div>`);
 if(tab==="Closure") b=nfCorpPanel("Audit Closure","CAPA validation → residual risk → closure memo → archive",`<div class="nf-stage-line">${["All Observations Resolved","Validation","Residual Risk","Closure Approval","Archive"].map((x,i)=>`<div class="${i<1?'done':i===1?'active':''}">${x}</div>`).join("")}</div><div class="notice info">Audit cannot be closed until all High and Critical observations are validated.</div>`);
 if(tab==="Reports") b=nfCorpPanel("Audit Analytics","Plan coverage, ageing, recurrence and CAPA effectiveness",`<div class="nf-quick-grid">${["Audit Plan","Observation Ageing","CAPA","Repeat Findings","Branch Score","Audit Trail"].map(x=>`<button onclick="showToast('${x} report exported')">${x}</button>`).join("")}</div>`);
 $("#content").innerHTML=`${nfCorpHero("INTERNAL AUDIT","Audit Management","Risk-based planning, fieldwork, observations, management response, CAPA validation and closure.",`<button class="primary" onclick="nfAuditNew()">＋ New Audit</button>`)}${nfCorpTabs(NF_AUDIT_TABS,tab,"nfAuditSetTab")}${b}`;
}
function nfAuditSetTab(t){nfCorp.auditTab=t;nfCorpSave();renderAuditManagement()}
function nfAuditNew(){showModal("Create Audit",`<div class="field-grid"><label>Audit Title<input id="nfAudTitle"></label><label>Type<select id="nfAudType"><option>Internal</option><option>Compliance</option><option>IT</option><option>Branch</option><option>Process</option></select></label><label>Scope<input id="nfAudScope"></label><label>Auditee<input id="nfAuditee"></label><label>Risk<select id="nfAudRisk"><option>Medium</option><option>High</option><option>Critical</option><option>Low</option></select></label><label>Due Date<input id="nfAudDue" type="date"></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfAuditSave()">Create</button>`)}
function nfAuditSave(){const title=$("#nfAudTitle").value.trim();if(!title)return;nfCorp.audits.unshift({id:"AUD-"+Date.now().toString().slice(-5),title,type:$("#nfAudType").value,scope:$("#nfAudScope").value,owner:currentUser.name,auditee:$("#nfAuditee").value,status:"Planning",risk:$("#nfAudRisk").value,start:nfToday(),due:$("#nfAudDue").value||nfToday(),progress:10});nfCorpSave();closeModal();showToast("Audit created");nfCorp.auditTab="Audit Plan";renderAuditManagement()}
