function nfAuditAddObservation(audit){showModal("Add Audit Observation",`<label>Observation<textarea id="nfObsTitle" rows="3"></textarea></label><div class="field-grid"><label>Rating<select id="nfObsRating"><option>Medium</option><option>High</option><option>Critical</option><option>Low</option></select></label><label>Owner<input id="nfObsOwner" value="Operations"></label><label>Due<input id="nfObsDue" type="date"></label><label>Management Response<input id="nfObsResponse"></label></div>`,`<button class="ghost-btn" onclick="closeModal()">Cancel</button><button class="primary-btn" onclick="nfAuditSaveObservation('${audit}')">Create</button>`)}
function nfAuditSaveObservation(audit){const title=$("#nfObsTitle").value.trim();if(!title)return;nfCorp.observations.unshift({id:"OBS-"+Date.now().toString().slice(-4),audit,title,rating:$("#nfObsRating").value,owner:$("#nfObsOwner").value,due:$("#nfObsDue").value||nfToday(),status:"Open",response:$("#nfObsResponse").value});nfCorpSave();closeModal();showToast("Observation created");renderAuditManagement()}
function nfAuditAdvanceObs(id){const o=nfCorp.observations.find(x=>x.id===id);if(!o)return;const s=["Open","Management Response","CAPA Submitted","Validation","Closed"],i=s.indexOf(o.status);o.status=s[Math.min(s.length-1,i<0?1:i+1)];nfCorpSave();showToast(o.id+" moved to "+o.status);renderAuditManagement()}

