const NF_CCTV_TABS=["Overview","Camera Health","Live Monitoring","Incidents","Footage Requests","Retention","Reports"];
function renderCCTVMonitoring(){
 nfCorpActivate("cctvMonitoring","CCTV Monitoring","Security / CCTV");const tab=nfCorp.cctvTab,c=nfCorp.cameras;let b="";
 if(tab==="Overview") b=`${nfCorpKpis([["Cameras",c.length,"Sample estate"],["Online",c.filter(x=>x.status==="Online").length,"Live"],["Offline",c.filter(x=>x.status==="Offline").length,"Needs action"],["Incidents",nfCorp.cctvIncidents.length,"Open / recent"],["Retention","90 Days","Standard target"]])}<div class="nf-corp-two">${nfCorpPanel("Camera Health","Branch and zone visibility",`<div class="nf-camera-grid">${c.map(x=>`<button onclick="nfCCTVOpen('${x.id}')"><div class="nf-camera-screen"><span>${x.status==='Online'?'● LIVE':'● OFFLINE'}</span><strong>CAM</strong><small>${nfEsc(x.branch)} · ${nfEsc(x.zone)}</small></div><footer><b>${nfEsc(x.id)}</b>${nfPill(x.status)}</footer></button>`).join("")}</div>`)}${nfCorpPanel("Security Alerts","Incidents and device exceptions",`<div class="nf-corp-list">${nfCorp.cctvIncidents.map(i=>`<div class="nf-corp-static"><span><b>${nfEsc(i.id)} · ${nfEsc(i.type)}</b><small>${nfEsc(i.branch)} · ${nfEsc(i.time)}</small></span>${nfPill(i.severity)}${nfPill(i.status)}</div>`).join("")}<div class="nf-corp-static"><span><b>Camera offline · CAM-UDP-01</b><small>Udaipur · Entrance · 18 min ago</small></span>${nfPill('Critical')}</div></div>`)}</div>`;
 if(tab==="Camera Health") b=nfCorpPanel("Camera & NVR Health","Online status, recording, storage, uptime and retention",nfCorpTable(["Camera","Branch / Zone","Health","Retention","Last Signal","Incidents","Status",""],c.map(x=>`<tr><td><b>${nfEsc(x.id)}</b></td><td>${nfEsc(x.branch)}<small>${nfEsc(x.zone)}</small></td><td><div class="nf-table-progress"><i style="width:${x.health}%"></i></div>${x.health}%</td><td>${x.retention} days</td><td>${nfEsc(x.last)}</td><td>${x.incidents}</td><td>${nfPill(x.status)}</td><td><button class="nf-mini" onclick="nfCCTVHealth('${x.id}')">Health Check</button></td></tr>`)));
 if(tab==="Live Monitoring") b=nfCorpPanel("Live Monitoring Wall","Prototype live-wall layout for authorized security roles",`<div class="nf-camera-wall">${c.map(x=>`<button onclick="nfCCTVOpen('${x.id}')" class="${x.status==='Offline'?'offline':''}"><header>${nfEsc(x.id)}<span>${nfEsc(x.status)}</span></header><div><strong>${x.status==='Online'?'LIVE FEED':'NO SIGNAL'}</strong><small>${nfEsc(x.branch)} · ${nfEsc(x.zone)}</small></div><footer>Retention ${x.retention}d · Health ${x.health}%</footer></button>`).join("")}</div>`);
 if(tab==="Incidents") b=nfCorpPanel("CCTV Incident Register","Detect → review → classify → evidence → action → closure",`<div class="nf-corp-list">${nfCorp.cctvIncidents.map(i=>`<div class="nf-corp-static"><span><b>${nfEsc(i.id)} · ${nfEsc(i.type)}</b><small>${nfEsc(i.camera)} · ${nfEsc(i.branch)} · ${nfEsc(i.time)}</small></span>${nfPill(i.severity)}${nfPill(i.status)}<button class="nf-mini" onclick="nfCCTVAdvanceIncident('${i.id}')">Advance</button></div>`).join("")}</div>`,`<button class="nf-mini primary" onclick="nfCCTVNewIncident()">＋ Log Incident</button>`);
 if(tab==="Footage Requests") b=nfCorpPanel("Footage Request & Evidence Export","Request → authorization → search → clip → hash → export → audit log",`<div class="nf-corp-list">${[["FR-101","Audit Manager","CAM-JPR-02","02 Oct 21:00-23:00","Approved"],["FR-102","Admin Manager","CAM-UDP-01","03 Oct 09:00-10:00","Pending Approval"]].map(x=>`<div class="nf-corp-static"><span><b>${x[0]} · ${x[2]}</b><small>${x[1]} · ${x[3]}</small></span>${nfPill(x[4])}<button class="nf-mini" onclick="showToast('Footage request opened')">Open</button></div>`).join("")}</div>`,`<button class="nf-mini primary" onclick="showToast('New footage request opened')">＋ Request Footage</button>`);
 if(tab==="Retention") b=nfCorpPanel("Retention & Storage","Policy, storage capacity, purge and legal hold",`${nfBars([["90-day cameras",82],["60-day cameras",12],["Storage utilized",73],["Legal hold clips",8]])}<div class="notice info" style="margin-top:14px">Retention settings are policy controlled. Evidence under legal/audit hold is excluded from automated purge.</div>`);
 if(tab==="Reports") b=nfCorpPanel("CCTV Reports","Uptime, incidents, footage access and retention controls",`<div class="nf-quick-grid">${["Uptime","Incidents","Footage Access","Storage","Offline Cameras","Retention"].map(x=>`<button onclick="showToast('${x} report exported')">${x}</button>`).join("")}</div>`);
 $("#content").innerHTML=`${nfCorpHero("SECURITY & SURVEILLANCE","CCTV Monitoring","Camera health, monitoring wall, incidents, footage requests, retention controls and evidence audit trail.",`<button class="primary" onclick="nfCCTVNewIncident()">＋ Log Incident</button>`)}${nfCorpTabs(NF_CCTV_TABS,tab,"nfCCTVSetTab")}${b}`;
}
